package com.example.project;

import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.*;
public class CustomGridActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_gridview);setTitle("CustomGridView 예제");List<CustomItem> items=Arrays.asList(new CustomItem(R.drawable.apple,"Apple"),new CustomItem(R.drawable.pear,"Pear"),new CustomItem(R.drawable.banana,"Banana"),new CustomItem(R.drawable.strawberry,"Strawberry"),new CustomItem(R.drawable.pineapple,"Pineapple"),new CustomItem(R.drawable.mango,"Mango"),new CustomItem(R.drawable.cherry,"Cherry"),new CustomItem(R.drawable.persimmon,"Persimmon"),new CustomItem(R.drawable.melon,"Melon"));GridView grid=findViewById(R.id.gridView);grid.setAdapter(new GridAdapter(this,items));grid.setOnItemClickListener((p,v,pos,id)->Toast.makeText(this,items.get(pos).getName(),Toast.LENGTH_SHORT).show());findViewById(R.id.button).setOnClickListener(v->finish());}}
